def validate_name(data):
    errors = []
    if 'name' not in data:
        errors.append('name is required')
    elif len(data['name']) < 2:
        errors.append('name must be at least 2 characters')
    elif len(data['name']) > 100:
        errors.append('name must be at most 100 characters')
    return errors

def validate_email(data):
    errors = []
    if 'email' not in data:
        errors.append('email is required')
    elif '@' not in data['email']:
        errors.append('email must contain @')
    elif len(data['email']) > 254:
        errors.append('email is too long')
    return errors

def validate_age(data):
    errors = []
    if 'age' not in data:
        errors.append('age is required')
    elif not isinstance(data['age'], int):
        errors.append('age must be an integer')
    elif data['age'] < 0 or data['age'] > 150:
        errors.append('age must be between 0 and 150')
    return errors

def validate_role(data):
    errors = []
    if 'role' not in data:
        errors.append('role is required')
    elif data['role'] not in ('admin', 'user', 'moderator'):
        errors.append('role must be admin, user, or moderator')
    return errors

FIELD_VALIDATORS = {
    'name': validate_name,
    'email': validate_email,
    'age': validate_age,
    'role': validate_role,
}

def validate_user_input(data):
    errors = []
    for field, validator in FIELD_VALIDATORS.items():
        errors.extend(validator(data))
    return errors
